import pytest
from freebusy import free_slots

WEEK = ("mon", "tue", "wed", "thu", "fri")
WEEKEND = ("sat", "sun")


class TestBasicFunctionality:
    """Test core free_slots functionality with simple cases."""

    def test_single_attendee_all_working_hours(self):
        """Single attendee with simple working hours in UTC."""
        alice = {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        result = free_slots(
            [alice], "2025-06-02T00:00Z", "2025-06-04T00:00Z", 60
        )
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z"),
            ("2025-06-03T09:00:00Z", "2025-06-03T17:00:00Z"),
        ]

    def test_no_working_hours_in_window(self):
        """Search window outside of working hours."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-01T00:00Z", "2025-06-02T00:00Z", 60)
        assert result == []

    def test_weekend_with_no_working_hours(self):
        """Attendee has no working hours on weekends."""
        alice = {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        result = free_slots([alice], "2025-06-07T00:00Z", "2025-06-09T00:00Z", 60)
        assert result == []

    def test_weekend_with_working_hours(self):
        """Attendee works on weekends."""
        alice = {"tz": "UTC", "hours": {"sat": ["10:00-18:00"], "sun": ["10:00-18:00"]}}
        result = free_slots([alice], "2025-06-07T00:00Z", "2025-06-09T00:00Z", 60)
        assert result == [
            ("2025-06-07T10:00:00Z", "2025-06-07T18:00:00Z"),
            ("2025-06-08T10:00:00Z", "2025-06-08T18:00:00Z"),
        ]


class TestMultipleAttendees:
    """Test scheduling with multiple attendees."""

    def test_two_attendees_same_timezone(self):
        """Multiple attendees in same timezone, overlapping hours."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        bob = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice, bob], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_two_attendees_different_hours(self):
        """Two attendees with different working hours."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-13:00"]}}
        bob = {"tz": "UTC", "hours": {"mon": ["11:00-15:00"]}}
        result = free_slots([alice, bob], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        assert result == [("2025-06-02T11:00:00Z", "2025-06-02T13:00:00Z")]

    def test_three_attendees_limited_overlap(self):
        """Three attendees with limited overlapping hours."""
        alice = {"tz": "UTC", "hours": {"mon": ["08:00-18:00"]}}
        bob = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        charlie = {"tz": "UTC", "hours": {"mon": ["10:00-16:00"]}}
        result = free_slots(
            [alice, bob, charlie], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60
        )
        assert result == [("2025-06-02T10:00:00Z", "2025-06-02T16:00:00Z")]

    def test_no_overlap_between_attendees(self):
        """Two attendees with no overlapping working hours."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-13:00"]}}
        bob = {"tz": "UTC", "hours": {"mon": ["14:00-18:00"]}}
        result = free_slots([alice, bob], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        assert result == []


class TestTimezones:
    """Test handling of different time zones."""

    def test_two_timezones_new_york_berlin(self):
        """Schedule meeting across New York and Berlin time zones."""
        ny = {"tz": "America/New_York", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        berlin = {"tz": "Europe/Berlin", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        result = free_slots([ny, berlin], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        # NY is UTC-4, Berlin is UTC+2, so there's a 6-hour overlap
        # NY 09:00-17:00 is 13:00-21:00 UTC
        # Berlin 09:00-17:00 is 07:00-15:00 UTC
        # Overlap is 13:00-15:00 UTC on June 2 (Monday for both)
        assert result == [("2025-06-02T13:00:00Z", "2025-06-02T15:00:00Z")]

    def test_three_timezones(self):
        """Schedule across three different time zones."""
        ny = {"tz": "America/New_York", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        london = {"tz": "Europe/London", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        tokyo = {"tz": "Asia/Tokyo", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        result = free_slots(
            [ny, london, tokyo], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30
        )
        # Very limited overlap between these three zones
        # This is a real challenge; the result may be empty
        assert isinstance(result, list)

    def test_positive_offset_timezone(self):
        """Attendee with positive UTC offset (Asia/Tokyo)."""
        tokyo = {"tz": "Asia/Tokyo", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([tokyo], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # Monday in Tokyo 09:00-17:00 JST is Monday 00:00-08:00 UTC
        assert result == [("2025-06-02T00:00:00Z", "2025-06-02T08:00:00Z")]

    def test_negative_offset_timezone(self):
        """Attendee with negative UTC offset (America/Los_Angeles)."""
        la = {"tz": "America/Los_Angeles", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([la], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # Monday in LA 09:00-17:00 PDT is Monday 16:00 UTC to Tuesday 00:00 UTC
        assert result == [
            ("2025-06-02T16:00:00Z", "2025-06-03T00:00:00Z"),
        ]

    def test_fractional_offset_timezone(self):
        """Timezone with fractional offset like Asia/Kolkata (+05:30)."""
        kolkata = {"tz": "Asia/Kolkata", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([kolkata], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # Monday in Kolkata 09:00-17:00 IST is Monday 03:30-11:30 UTC
        assert result == [("2025-06-02T03:30:00Z", "2025-06-02T11:30:00Z")]


class TestBusyPeriods:
    """Test handling of busy time blocks."""

    def test_one_busy_period(self):
        """Single busy period within working hours."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}, "busy": [["2025-06-02T12:00:00Z", "2025-06-02T13:00:00Z"]]}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T12:00:00Z"),
            ("2025-06-02T13:00:00Z", "2025-06-02T17:00:00Z"),
        ]

    def test_multiple_busy_periods(self):
        """Multiple non-overlapping busy periods."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [
                ["2025-06-02T10:00:00Z", "2025-06-02T11:00:00Z"],
                ["2025-06-02T13:00:00Z", "2025-06-02T14:00:00Z"],
            ],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T10:00:00Z"),
            ("2025-06-02T11:00:00Z", "2025-06-02T13:00:00Z"),
            ("2025-06-02T14:00:00Z", "2025-06-02T17:00:00Z"),
        ]

    def test_busy_period_covers_all_free_time(self):
        """Busy period completely covers potential free time."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        assert result == []

    def test_busy_period_outside_window(self):
        """Busy period completely outside search window."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"], "tue": ["09:00-17:00"]},
            "busy": [["2025-06-01T10:00:00Z", "2025-06-01T11:00:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-04T00:00Z", 60)
        # Busy period is on June 1, so shouldn't affect June 2-3
        assert len(result) == 2

    def test_overlapping_busy_periods(self):
        """Overlapping busy periods are merged."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [
                ["2025-06-02T10:00:00Z", "2025-06-02T12:00:00Z"],
                ["2025-06-02T11:00:00Z", "2025-06-02T13:00:00Z"],
            ],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # Merged busy is 10:00-13:00
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T10:00:00Z"),
            ("2025-06-02T13:00:00Z", "2025-06-02T17:00:00Z"),
        ]

    def test_busy_period_with_timezone_offset(self):
        """Busy period specified with timezone offset."""
        tokyo = {
            "tz": "Asia/Tokyo",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T12:00:00+09:00", "2025-06-02T13:00:00+09:00"]],
        }
        result = free_slots([tokyo], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # 09:00-17:00 JST is 00:00-08:00 UTC
        # Busy 12:00-13:00 JST is 03:00-04:00 UTC
        assert result == [
            ("2025-06-02T00:00:00Z", "2025-06-02T03:00:00Z"),
            ("2025-06-02T04:00:00Z", "2025-06-02T08:00:00Z"),
        ]


class TestWorkingHoursFormats:
    """Test various working hours formats and edge cases."""

    def test_single_hour_working_window(self):
        """Very short working hours."""
        alice = {"tz": "UTC", "hours": {"mon": ["14:00-15:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        assert result == []  # Only 1 hour, min_minutes is 60

    def test_exactly_min_minutes(self):
        """Working period exactly matches min_minutes."""
        alice = {"tz": "UTC", "hours": {"mon": ["14:00-15:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        assert result == []  # Only 1 hour (60 minutes) is not >= 60 for the minimum

    def test_just_above_min_minutes(self):
        """Working period just above min_minutes."""
        alice = {"tz": "UTC", "hours": {"mon": ["14:00-15:01"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # 1 hour 1 minute is > 60 minutes
        assert len(result) >= 0  # Depends on min_minutes comparison

    def test_hours_wrapping_midnight(self):
        """Working hours that cross midnight (22:00-06:00)."""
        alice = {"tz": "UTC", "hours": {"mon": ["22:00-06:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # Monday 22:00 UTC to Tuesday 06:00 UTC
        # So on June 2: 22:00-23:59 (can't get 60 min), on June 3: 00:00-06:00 (6 hours)
        assert ("2025-06-03T00:00:00Z", "2025-06-03T06:00:00Z") in result

    def test_hours_ending_at_24_00(self):
        """Working hours ending at 24:00 (midnight end of day)."""
        alice = {"tz": "UTC", "hours": {"mon": ["18:00-24:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # Monday 18:00 to Tuesday 00:00 (6 hours)
        assert result == [("2025-06-02T18:00:00Z", "2025-06-03T00:00:00Z")]

    def test_multiple_entries_per_day(self):
        """Multiple working-hours entries for the same weekday."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-12:00", "13:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        # Both periods combined
        assert len(result) == 2
        assert result[0] == ("2025-06-02T09:00:00Z", "2025-06-02T12:00:00Z")
        assert result[1] == ("2025-06-02T13:00:00Z", "2025-06-02T17:00:00Z")

    def test_overlapping_entries_per_day(self):
        """Overlapping working-hours entries for the same weekday."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-13:00", "11:00-15:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # Union is 09:00-15:00 (6 hours)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T15:00:00Z")]

    def test_touching_entries_per_day(self):
        """Working-hours entries that touch end-to-end."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-12:00", "12:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # Should be treated as continuous 09:00-17:00
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]


class TestMinutesFiltering:
    """Test min_minutes filtering."""

    def test_min_minutes_1(self):
        """Minimum slot is 1 minute."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-09:01"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 1)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T09:01:00Z")]

    def test_min_minutes_large(self):
        """Large minimum slot requirement filters results."""
        alice = {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-04T00:00Z", 1200)
        # 20 hours minimum needed
        assert len(result) == 0  # Each day is only 8 hours

    def test_min_minutes_exact_boundary(self):
        """Test slots exactly at the min_minutes boundary."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-10:00"]}}
        result_60 = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # Exactly 60 minutes
        assert result_60 == [("2025-06-02T09:00:00Z", "2025-06-02T10:00:00Z")]

    def test_min_minutes_one_minute_short(self):
        """Slot one minute short of minimum."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-09:59"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # Only 59 minutes, should be filtered
        assert result == []


class TestDaylightSavingTime:
    """Test handling of daylight saving time transitions."""

    def test_spring_forward_america_new_york(self):
        """Spring forward (clock moves ahead) in America/New_York."""
        # 2025-03-09 at 02:00 EST, clocks jump to 03:00 EDT
        ny = {
            "tz": "America/New_York",
            "hours": {"sun": ["02:00-04:00"]},
        }
        result = free_slots([ny], "2025-03-09T00:00Z", "2025-03-10T00:00Z", 1)
        # Entry "02:00-04:00" covers from 07:00Z to 08:00Z (03:00 to 04:00 EDT)
        # The 02:30-03:00 wall-clock time doesn't exist, so entry at 02:30 covers nothing
        assert len(result) >= 0

    def test_fall_back_america_new_york(self):
        """Fall back (clock moves back) in America/New_York."""
        # 2025-11-02 at 02:00 EDT, clocks fall back to 01:00 EST
        ny = {
            "tz": "America/New_York",
            "hours": {"sun": ["00:00-03:00"]},
        }
        result = free_slots([ny], "2025-11-02T00:00Z", "2025-11-03T00:00Z", 1)
        # Entry "00:00-03:00" covers both EDT and EST periods
        # Should be 04:00Z to 08:00Z (4 hours total, with 1:00-1:59 appearing twice)
        assert len(result) > 0

    def test_before_spring_forward(self):
        """Working hours before spring forward don't change."""
        ny = {
            "tz": "America/New_York",
            "hours": {"fri": ["09:00-17:00"], "sat": ["09:00-17:00"]},
        }
        result = free_slots([ny], "2025-03-07T00:00Z", "2025-03-09T00:00Z", 60)
        # Friday and Saturday before the change are normal
        assert len(result) >= 2

    def test_after_fall_back(self):
        """Working hours after fall back don't change."""
        ny = {
            "tz": "America/New_York",
            "hours": {"sun": ["09:00-17:00"], "mon": ["09:00-17:00"]},
        }
        result = free_slots([ny], "2025-11-02T00:00Z", "2025-11-04T00:00Z", 60)
        # Sunday and Monday after the change are normal
        assert len(result) >= 1


class TestTimestampFormats:
    """Test various timestamp formats."""

    def test_timestamp_with_seconds(self):
        """Timestamp with seconds component."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots(
            [alice], "2025-06-02T00:00:00Z", "2025-06-03T00:00:00Z", 60
        )
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_timestamp_without_seconds(self):
        """Timestamp without seconds component."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_timestamp_with_positive_offset(self):
        """Timestamp with positive UTC offset."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots(
            [alice], "2025-06-02T09:00:00+05:00", "2025-06-02T17:00:00+05:00", 60
        )
        # Same as 2025-06-02T04:00Z to 2025-06-02T12:00Z
        assert len(result) >= 0

    def test_timestamp_with_negative_offset(self):
        """Timestamp with negative UTC offset."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots(
            [alice], "2025-06-02T09:00:00-05:00", "2025-06-02T17:00:00-05:00", 60
        )
        # Same as 2025-06-02T14:00Z to 2025-06-02T22:00Z
        assert len(result) >= 0

    def test_timestamp_with_fractional_offset(self):
        """Timestamp with fractional UTC offset like +05:45."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots(
            [alice], "2025-06-02T10:00:00+05:45", "2025-06-02T18:00:00+05:45", 60
        )
        assert len(result) >= 0


class TestErrorCases:
    """Test error handling as specified."""

    def test_empty_attendees_list(self):
        """Empty attendees list raises ValueError."""
        with pytest.raises(ValueError):
            free_slots([], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)

    def test_invalid_timezone(self):
        """Unknown time zone raises ValueError."""
        alice = {"tz": "Invalid/Zone", "hours": {"mon": ["09:00-17:00"]}}
        with pytest.raises(ValueError):
            free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)

    def test_invalid_weekday_name(self):
        """Invalid weekday name in hours dict raises ValueError."""
        alice = {"tz": "UTC", "hours": {"monday": ["09:00-17:00"]}}
        with pytest.raises(ValueError):
            free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)

    def test_invalid_hours_format_bad_separator(self):
        """Invalid hours format (wrong separator) raises ValueError."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00_17:00"]}}
        with pytest.raises(ValueError):
            free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)

    def test_invalid_hours_format_missing_minutes(self):
        """Invalid hours format (missing minutes) raises ValueError."""
        alice = {"tz": "UTC", "hours": {"mon": ["09-17"]}}
        with pytest.raises(ValueError):
            free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)

    def test_invalid_hours_format_bad_hour(self):
        """Invalid hours format (invalid hour value) raises ValueError."""
        alice = {"tz": "UTC", "hours": {"mon": ["25:00-26:00"]}}
        with pytest.raises(ValueError):
            free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)

    def test_invalid_hours_format_bad_minute(self):
        """Invalid hours format (invalid minute value) raises ValueError."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:60-17:00"]}}
        with pytest.raises(ValueError):
            free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)

    def test_invalid_hours_start_equals_end(self):
        """Working hours where start equals end raises ValueError."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-09:00"]}}
        with pytest.raises(ValueError):
            free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)

    def test_invalid_hours_end_at_24_00_but_as_time(self):
        """Hours with 24:00 as end is valid, but other values > 23 are not."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-25:00"]}}
        with pytest.raises(ValueError):
            free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)

    def test_timestamp_missing_offset(self):
        """Timestamp without UTC offset raises ValueError."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
