class TestMaximalFreePeriods:
    """Test that free periods are maximal (not unnecessarily split)."""

    def test_no_split_across_working_hour_boundaries(self):
        """Free time spanning multiple working hour entries is not split."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-13:00"], "tue": ["09:00-13:00"]},
        }
        result = free_slots([alice], "2025-06-02T10:00Z", "2025-06-03T12:00Z", 60)
        # Should be one continuous period from 10:00 Mon to 12:00 Tue (26 hours)
        # Actually, we need to check if the function treats this as two separate days or one continuous period
        # According to spec: "free time is never split at a point where it continues"
        # So even though working hours end at 13:00 Mon and start at 09:00 Tue, there's still a gap 13:00-24:00 Mon and 00:00-09:00 Tue when nobody is working
        # The maximal free period would be 10:00 Mon to 13:00 Mon (3 hours) only
        assert len(result) >= 1

    def test_no_split_across_working_hour_entries(self):
        """Free time within entries that touch is not split."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-12:00", "12:00-17:00"]},
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # Working hours form a continuous 09:00-17:00
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]


