class TestSpecialCases:
    """Test special and complex cases from the spec examples."""

    def test_example_from_spec_spring_forward(self):
        """Test the spring forward example from the spec."""
        # In America/New_York on Sunday 2025-03-09 the clocks jump from 02:00 EST
        # to 03:00 EDT at 07:00Z. Entry "02:30-04:00" covers 07:00Z to 08:00Z
        ny = {
            "tz": "America/New_York",
            "hours": {"sun": ["02:30-04:00"]},
        }
        result = free_slots([ny], "2025-03-09T00:00Z", "2025-03-10T00:00Z", 1)
        # The 02:30-03:00 wall-clock time doesn't exist (clocks skip forward)
        # So "02:30-04:00" should cover 07:00Z-08:00Z (03:00-04:00 EDT)
        assert any(start <= "2025-03-09T07:00:00Z" and end >= "2025-03-09T08:00:00Z" for start, end in result)

    def test_no_free_time_in_window(self):
        """Return empty list when there's no free time."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-10:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-02T09:00Z", 60)
        assert result == []

