class TestTimezones:
    """Test time zone conversions."""

    def test_different_timezones_utc_format(self):
        """Different time zones using Z format."""
        ny = {"tz": "America/New_York", "hours": {"mon": ["09:00-17:00"]}}
        berlin = {"tz": "Europe/Berlin", "hours": {"mon": ["09:00-17:00"]}}
        # 2025-06-02 is Monday for both
        # NY: 09:00-17:00 EDT (UTC-4) = 13:00-21:00 UTC
        # Berlin: 09:00-17:00 CEST (UTC+2) = 07:00-15:00 UTC
        # Overlap: 13:00-15:00 UTC
        result = free_slots([ny, berlin], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == [("2025-06-02T13:00:00Z", "2025-06-02T15:00:00Z")]

