        """Timestamps with positive UTC offsets."""
        tokyo = {"tz": "Asia/Tokyo", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([tokyo], "2025-06-02T00:00+09:00", "2025-06-03T00:00+09:00", 30)
        # Same as UTC but with different offset notation
        assert len(result) == 1
        assert result[0][0].endswith("Z")  # Output always in UTC

    def test_negative_offset_format(self):
        """Timestamps with negative UTC offsets."""
        la = {"tz": "America/Los_Angeles", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([la], "2025-06-02T00:00-07:00", "2025-06-03T00:00-07:00", 30)
        assert len(result) == 1
        assert result[0][0].endswith("Z")

    def test_fractional_offset(self):
        """Timestamps with fractional UTC offsets."""
        kathmandu = {"tz": "Asia/Kathmandu", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([kathmandu], "2025-06-02T00:00+05:45", "2025-06-03T00:00+05:45", 30)
        assert len(result) == 1
        assert result[0][0].endswith("Z")

