        alice = {"tz": "UTC", "hours": {"mon": ["09:00-10:00"]}}
        # 2025-06-02T09:00:00+05:00 is 2025-06-02T04:00:00Z
        result = free_slots([alice], "2025-06-02T04:00:00Z", "2025-06-02T05:00:00Z", 30)
