class TestDSTTransitions:
    """Test daylight saving time transitions."""

    def test_spring_forward_gap(self):
        """Test spring forward transition that creates a gap."""
        # In America/New_York on 2025-03-09, clocks jump from 02:00 EST to 03:00 EDT
        # So 02:30 doesn't exist in that time zone
        ny = {"tz": "America/New_York", "hours": {"sun": ["02:30-04:00"]}}
        result = free_slots([ny], "2025-03-09T00:00Z", "2025-03-10T00:00Z", 1)
        # 02:30-04:00 on Sunday: 02:30 is in the gap, so this entry has limited coverage
        # At 07:00Z the clocks jump to 03:00 EDT, which is 07:00Z
        # So the entry covers 03:00-04:00 EDT = 07:00-08:00Z
        assert any("2025-03-09T07:00:00Z" in slot for slot in result)

    def test_fall_back_overlap(self):
        """Test fall back transition that creates an overlap."""
        # In America/New_York on 2025-11-02, clocks fall back from 01:59 EDT to 01:00 EST
        # So 01:00-01:59 is shown twice
        ny = {"tz": "America/New_York", "hours": {"sun": ["00:00-03:00"]}}
        result = free_slots([ny], "2025-11-02T00:00Z", "2025-11-03T00:00Z", 1)
        # This should cover the transition period
        # On EDT: 00:00-02:00 EDT = 04:00-06:00Z
        # On EST: 00:00-03:00 EST = 05:00-08:00Z
        # Together: 04:00-08:00Z with 05:00-06:00 covered twice
        assert len(result) >= 1


