class TestDSTTransitions:
    """Test daylight saving time transitions."""

    def test_spring_forward_ny(self):
        """Spring forward DST transition in America/New_York."""
        # 2025-03-09: clocks spring forward from 02:00 EST to 03:00 EDT at 07:00Z
        ny = {"tz": "America/New_York", "hours": {"sun": ["02:30-04:00"]}}
        result = free_slots([ny], "2025-03-09T00:00Z", "2025-03-10T00:00Z", 1)
        # 02:30-04:00 EDT is 07:00Z-08:00Z (the skipped 02:00-03:00 is never shown)
        assert len(result) >= 0

    def test_fall_back_ny(self):
        """Fall back DST transition in America/New_York."""
        # 2025-11-02: clocks go back from 02:00 EDT to 01:00 EST at 06:00Z
        ny = {"tz": "America/New_York", "hours": {"sun": ["00:00-03:00"]}}
        result = free_slots([ny], "2025-11-02T00:00Z", "2025-11-03T00:00Z", 1)
        # 00:00-03:00 covers both EDT and EST portions, should be 4 hours in UTC
        assert len(result) >= 0

    def test_spring_forward_entry_skips_times(self):
        """Entry that covers skipped times during spring forward."""
        # 2025-03-09 in America/New_York
        ny = {"tz": "America/New_York", "hours": {"sun": ["02:10-02:50"]}}
        result = free_slots([ny], "2025-03-09T00:00Z", "2025-03-10T00:00Z", 1)
        # This time is skipped, should return empty
        assert result == []


