        alice = {"tz": "UTC", "hours": {"mon": ["09:00-09:00"]}}
        with pytest.raises(ValueError):
            free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)

    def test_hours_24_00_as_end(self):
        """24:00 is valid as an end time."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-24:00"]}}
