        assert len(result) >= 0

    def test_hours_24_00_invalid_start(self):
        """24:00 is not valid as a start time."""
        alice = {"tz": "UTC", "hours": {"mon": ["24:00-06:00"]}}
        with pytest.raises(ValueError):
            free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)

    def test_hours_24_00_as_both(self):
        """24:00 as both start and end should fail (differ requirement)."""
        alice = {"tz": "UTC", "hours": {"mon": ["24:00-24:00"]}}
        with pytest.raises(ValueError):
