class TestResultOrdering:
    """Test that results are properly ordered."""

    def test_results_sorted_by_start(self):
        """Results should be sorted by start time."""
        alice = {
            "tz": "UTC",
            "hours": {d: ["09:00-17:00"] for d in WEEK},
            "busy": [
                ["2025-06-02T12:00:00Z", "2025-06-02T13:00:00Z"],
                ["2025-06-03T12:00:00Z", "2025-06-03T13:00:00Z"],
            ],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-04T00:00Z", 30)
        # Check that slots are in order by start time
        for i in range(len(result) - 1):
            assert result[i][0] < result[i + 1][0]

    def test_no_overlapping_results(self):
        """Results should never overlap."""
        alice = {
            "tz": "UTC",
            "hours": {d: ["09:00-17:00"] for d in WEEK},
            "busy": [
                ["2025-06-02T12:00:00Z", "2025-06-02T13:00:00Z"],
                ["2025-06-03T12:00:00Z", "2025-06-03T13:00:00Z"],
            ],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-04T00:00Z", 1)
        # Check that slots don't overlap
        for i in range(len(result) - 1):
            assert result[i][1] <= result[i + 1][0]

    def test_no_adjacent_slots(self):
        """Adjacent free periods should be merged into one slot."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-12:00", "14:00-17:00"]},
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 1)
        # Should return 2 slots (morning and afternoon) not merged
        assert len(result) == 2


class TestTimezoneConversions:
    """Test that timezone conversions are correct."""

    def test_tokyo_to_utc_conversion(self):
        """Tokyo is UTC+9."""
        tokyo = {
            "tz": "Asia/Tokyo",
            "hours": {"mon": ["09:00-10:00"]},
        }
        result = free_slots([tokyo], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 1)
        # Tokyo 09:00-10:00 is UTC 00:00-01:00
        assert result == [("2025-06-02T00:00:00Z", "2025-06-02T01:00:00Z")]

    def test_ny_to_utc_conversion(self):
        """New York is UTC-4 or UTC-5 depending on DST."""
        ny = {
            "tz": "America/New_York",
            "hours": {"mon": ["09:00-10:00"]},
        }
        # June is EDT (UTC-4)
        result = free_slots([ny], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 1)
        # NY 09:00-10:00 EDT is UTC 13:00-14:00
        assert result == [("2025-06-02T13:00:00Z", "2025-06-02T14:00:00Z")]
